package com.cleanpilot.model;

import com.cleanpilot.ui.FormatUtils;

import java.util.List;

/**
 * Result data snapshot generated by the 1-Click Smart Clean & Boost engine.
 */
public record SmartCleanResult(
        long temporaryFilesCleanedCount,
        long temporaryBytesCleaned,
        long crashDumpsCleanedCount,
        long crashDumpsBytesCleaned,
        long browserCacheBytesCleaned,
        long expiredQuarantineItemsPurged,
        long quarantineBytesPurged,
        long memoryBytesTrimmed,
        long totalBytesReclaimed,
        List<String> details
) {
    public String formattedTotalReclaimed() {
        return FormatUtils.formatBytes(totalBytesReclaimed);
    }

    public String formattedMemoryTrimmed() {
        return FormatUtils.formatBytes(memoryBytesTrimmed);
    }

    public long totalFilesCleaned() {
        return temporaryFilesCleanedCount + crashDumpsCleanedCount + expiredQuarantineItemsPurged;
    }
}
